script:
var anchorTag = root_element.getElementById("lead-action")
anchorTag.addEventListener('click',reRoute)

function reRoute(e){
    e.preventDefault()
    var todayDate = new Date()


    frappe.set_route("app","lead",{next_action_date:`${todayDate.getFullYear()}-${todayDate.getMonth()+1}-${todayDate.getDate()}`})
}
